/**
 * GCP Terraform code generator.
 *
 * Takes an array of {@link TranslatedResource} objects (produced by the
 * translation engines) and emits a set of `.tf` files ready for
 * `terraform init && terraform plan`.
 *
 * Output files:
 * - `main.tf`       -- resource blocks sorted by (targetType, targetName)
 * - `providers.tf`  -- `provider "google"` with project/region
 * - `terraform.tf`  -- `required_providers` block
 * - `variables.tf`  -- project_id, region, zone, environment
 * - `outputs.tf`    -- project_id, region passthroughs
 *
 * @module codegen/gcp-codegen
 * @generated by code-generator (TASK-TRANS-007)
 */

import type { TranslatedResource } from '@tla/shared';
import { createComponentLogger } from '@tla/shared';

import {
  literal,
  expr,
  list,
  writeResourceBlock,
  writeProviderBlock,
  writeTerraformBlock,
  writeVariableBlock,
  writeOutputBlock,
} from './hcl-writer.js';
import type { HclValue, HclMapEntry, HclMap, HclBlock } from './hcl-writer.js';
import { resolveGcpRegion } from './gcp/region-mapping.js';
import { sanitizeGcpName } from './gcp/naming.js';
import { transformLabels } from './gcp/label-transformer.js';

const logger = createComponentLogger('gcp-codegen');

// ---------------------------------------------------------------------------
// Options
// ---------------------------------------------------------------------------

/**
 * Options for the GCP code generator.
 */
export interface GcpGenOptions {
  /** AWS source region for location mapping. Default `'us-east-1'`. */
  readonly sourceRegion?: string;
  /** Terraform variable name for the GCP project ID. Default `'project_id'`. */
  readonly projectIdVar?: string;
  /** Environment tag value. Default `'dev'`. */
  readonly environment?: string;
  /** Emit `# Source:` and `# Required API:` comments above resource blocks. Default `true`. */
  readonly emitComments?: boolean;
  /** Sort attributes alphabetically within each resource. Default `true`. */
  readonly sortKeys?: boolean;
}

// ---------------------------------------------------------------------------
// Generated file map
// ---------------------------------------------------------------------------

export type GeneratedFiles = Map<string, string>;

// ---------------------------------------------------------------------------
// Block key detection set
// ---------------------------------------------------------------------------

/**
 * Attribute keys that must be rendered as HCL blocks (no `=`, no commas)
 * rather than map literals. Exception: `labels` is always a map.
 */
const GCP_BLOCK_KEYS: ReadonlySet<string> = new Set([
  'boot_disk',
  'initialize_params',
  'network_interface',
  'access_config',
  'scheduling',
  'service_account',
  'disk',
  'version',
  'autoscaling_policy',
  'node_config',
  'ip_allocation_policy',
  'settings',
  'ip_configuration',
  'build_config',
  'service_config',
  'event_trigger',
  'template',
  'containers',
  'scaling',
  'conditions',
  'condition_threshold',
  'aggregations',
  'allow',
  'deny',
  'node_pool',
  'private_visibility_config',
  'networks',
]);

// ---------------------------------------------------------------------------
// Type short map
// ---------------------------------------------------------------------------

/**
 * Maps `google_*` resource type strings to short abbreviations for naming.
 */
const GCP_TYPE_SHORT_MAP: ReadonlyMap<string, string> = new Map([
  ['google_compute_instance', 'vm'],
  ['google_compute_network', 'vpc'],
  ['google_compute_subnetwork', 'subnet'],
  ['google_container_cluster', 'gke'],
  ['google_sql_database_instance', 'sql'],
  ['google_storage_bucket', 'gcs'],
  ['google_kms_crypto_key', 'kms'],
  ['google_secret_manager_secret', 'secret'],
  ['google_redis_instance', 'redis'],
  ['google_compute_firewall', 'fw'],
  ['google_cloud_run_v2_service', 'run'],
  ['google_cloudfunctions2_function', 'func'],
  ['google_compute_instance_group_manager', 'mig'],
  ['google_monitoring_alert_policy', 'alert'],
  ['google_pubsub_topic', 'pubsub'],
]);

// ---------------------------------------------------------------------------
// API comment map (prefix-based)
// ---------------------------------------------------------------------------

/**
 * Maps GCP resource type prefixes to the required API service.
 */
const GCP_API_MAP: ReadonlyArray<readonly [string, string]> = [
  ['google_compute_', 'compute.googleapis.com'],
  ['google_storage_', 'storage.googleapis.com'],
  ['google_container_', 'container.googleapis.com'],
  ['google_sql_', 'sqladmin.googleapis.com'],
  ['google_cloudfunctions', 'cloudfunctions.googleapis.com'],
  ['google_cloud_run', 'run.googleapis.com'],
  ['google_kms_', 'cloudkms.googleapis.com'],
  ['google_secret_manager_', 'secretmanager.googleapis.com'],
  ['google_redis_', 'redis.googleapis.com'],
  ['google_monitoring_', 'monitoring.googleapis.com'],
  ['google_pubsub_', 'pubsub.googleapis.com'],
];

/**
 * Resolves the required GCP API for a resource type string.
 */
function resolveApi(gcpType: string): string | undefined {
  for (const [prefix, api] of GCP_API_MAP) {
    if (gcpType.startsWith(prefix)) return api;
  }
  return undefined;
}

// ---------------------------------------------------------------------------
// Value conversion
// ---------------------------------------------------------------------------

/**
 * Converts an arbitrary JS value (from TranslatedResource.attributes) into
 * an {@link HclValue} using the heuristics described in the architecture.
 *
 * @internal Exported for unit-test access only. Not part of the public API
 *           contract -- prefer {@link GcpCodeGenerator.generate} for
 *           external consumers.
 * @param value     - The value to convert.
 * @param parentKey - The attribute key that holds this value (used for
 *                    block-vs-map disambiguation).
 */
export function convertValue(value: unknown, parentKey?: string): HclValue {
  if (value === null || value === undefined) {
    return literal(null);
  }
  if (typeof value === 'boolean') {
    return literal(value);
  }
  if (typeof value === 'number') {
    return literal(value);
  }
  if (typeof value === 'string') {
    // Terraform interpolation: ${...} -> expression
    const interpMatch = /^\$\{(.+)\}$/.exec(value);
    if (interpMatch) {
      return expr(interpMatch[1]!);
    }
    return literal(value);
  }

  if (Array.isArray(value)) {
    // Arrays of objects where the parent key is a block key -> blocks
    if (
      value.length > 0 &&
      value.every((v) => typeof v === 'object' && v !== null && !Array.isArray(v)) &&
      parentKey !== undefined &&
      GCP_BLOCK_KEYS.has(parentKey)
    ) {
      const blockEntries: HclMapEntry[] = value.map((item) => ({
        key: parentKey,
        value: convertObject(item as Record<string, unknown>, true),
      }));
      return { kind: 'blocks', blocks: blockEntries };
    }
    // Regular list
    return list(value.map((v) => convertValue(v)));
  }

  if (typeof value === 'object') {
    // Special handling for tags -> labels transformation
    if (parentKey === 'tags' || parentKey === 'labels') {
      const tagObj = value as Record<string, string>;
      const { labels, warnings } = transformLabels(tagObj);
      if (warnings.length > 0) {
        logger.debug({ warnings }, 'Label transform warnings');
      }
      const entries: HclMapEntry[] = Object.keys(labels)
        .sort()
        .map((k) => ({ key: k, value: literal(labels[k]!) }));
      return { kind: 'map' as const, entries };
    }
    return convertObject(value as Record<string, unknown>, isBlockKey(parentKey));
  }

  // Fallback -- stringify
  return literal(String(value));
}

/**
 * Converts a plain object to either an HclMap or HclBlock.
 */
function convertObject(
  obj: Record<string, unknown>,
  asBlock: boolean,
): HclMap | HclBlock {
  const entries: HclMapEntry[] = Object.keys(obj).map((k) => ({
    key: k,
    value: convertValue(obj[k], k),
  }));

  if (asBlock) {
    return { kind: 'block', body: entries };
  }
  return { kind: 'map', entries };
}

/**
 * Determines whether a key should produce a block (not a map).
 * `labels` is always a map; keys in GCP_BLOCK_KEYS are blocks.
 */
function isBlockKey(key: string | undefined): boolean {
  if (key === undefined) return false;
  if (key === 'labels') return false;
  if (key === 'tags') return false;
  return GCP_BLOCK_KEYS.has(key);
}

// ---------------------------------------------------------------------------
// Resource conversion
// ---------------------------------------------------------------------------

/**
 * Converts a TranslatedResource's attributes into an array of HclMapEntry.
 */
function resourceToEntries(
  resource: TranslatedResource,
  sortKeys: boolean,
): HclMapEntry[] {
  const attrs = resource.attributes as Record<string, unknown>;
  const keys = sortKeys
    ? Object.keys(attrs).sort((a, b) => a.localeCompare(b))
    : Object.keys(attrs);

  return keys.map((k) => ({ key: k, value: convertValue(attrs[k], k) }));
}

// ---------------------------------------------------------------------------
// File generators
// ---------------------------------------------------------------------------

function generateMainTf(
  resources: readonly TranslatedResource[],
  options: Required<GcpGenOptions>,
): string {
  const sorted = [...resources].sort((a, b) => {
    const typeCmp = a.targetType.localeCompare(b.targetType);
    return typeCmp !== 0 ? typeCmp : a.targetName.localeCompare(b.targetName);
  });

  const blocks: string[] = [];

  // GCP has no resource group equivalent -- go straight to resources

  for (const resource of sorted) {
    const entries = resourceToEntries(resource, options.sortKeys);

    const commentParts: string[] = [];
    if (options.emitComments) {
      commentParts.push(
        `Source: ${resource.traceability.sourceType} (${resource.sourceId}), engine: ${resource.traceability.engineUsed}, confidence: ${resource.traceability.confidence}`,
      );
      const api = resolveApi(resource.targetType);
      if (api) {
        commentParts.push(`Required API: ${api}`);
      }
    }

    const comment = commentParts.length > 0
      ? commentParts.join('\n# ')
      : undefined;

    blocks.push(
      writeResourceBlock(
        resource.targetType,
        sanitizeGcpName(
          extractTypeShort(resource.targetType),
          resource.targetName,
        ),
        entries,
        { comment, sortKeys: options.sortKeys },
      ),
    );
  }

  if (blocks.length === 0) {
    return '# No resources translated\n';
  }

  return blocks.join('\n\n') + '\n';
}

function generateProvidersTf(options: Required<GcpGenOptions>): string {
  const body: HclMapEntry[] = [
    { key: 'project', value: expr(`var.${options.projectIdVar}`) },
    { key: 'region', value: expr('var.region') },
  ];

  return writeProviderBlock('google', body) + '\n';
}

function generateTerraformTf(): string {
  const googleProvider: HclMapEntry[] = [
    {
      key: 'google',
      value: {
        kind: 'block' as const,
        body: [
          { key: 'source', value: literal('hashicorp/google') },
          { key: 'version', value: literal('~> 5.0') },
        ],
      },
    },
  ];

  const body: HclMapEntry[] = [
    {
      key: 'required_providers',
      value: { kind: 'block' as const, body: googleProvider },
    },
  ];

  return writeTerraformBlock(body) + '\n';
}

function generateVariablesTf(
  options: Required<GcpGenOptions>,
): string {
  const gcpRegion = resolveGcpRegion(options.sourceRegion);

  const blocks: string[] = [
    writeVariableBlock('project_id', {
      description: 'GCP project ID',
      type: 'string',
      sensitive: true,
    }),
    writeVariableBlock('region', {
      description: 'GCP region for all resources',
      type: 'string',
      defaultValue: literal(gcpRegion),
    }),
    writeVariableBlock('zone', {
      description: 'GCP zone for zonal resources',
      type: 'string',
      defaultValue: literal(gcpRegion + '-b'),
    }),
    writeVariableBlock('environment', {
      description: 'Deployment environment',
      type: 'string',
      defaultValue: literal(options.environment),
    }),
  ];

  return blocks.join('\n\n') + '\n';
}

function generateOutputsTf(): string {
  const blocks: string[] = [
    writeOutputBlock('project_id', {
      description: 'The GCP project ID',
      value: expr('var.project_id'),
      sensitive: true,
    }),
    writeOutputBlock('region', {
      description: 'The GCP region',
      value: expr('var.region'),
    }),
  ];

  return blocks.join('\n\n') + '\n';
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Extracts a short type key from a `google_*` resource type string.
 * E.g. `'google_compute_instance'` -> `'vm'`.
 */
function extractTypeShort(gcpType: string): string {
  return GCP_TYPE_SHORT_MAP.get(gcpType) ?? 'resource';
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * GCP Terraform code generator.
 *
 * Stateless -- construct and call {@link generate} with resources and options.
 */
export class GcpCodeGenerator {
  /**
   * Generates a set of `.tf` files from translated resources.
   *
   * @param resources - Translated GCP resources from the engine pipeline.
   * @param options   - Generation options (all optional with sensible defaults).
   * @returns A Map of filename -> file content.
   */
  generate(
    resources: readonly TranslatedResource[],
    options?: GcpGenOptions,
  ): GeneratedFiles {
    const resolved: Required<GcpGenOptions> = {
      sourceRegion: options?.sourceRegion ?? 'us-east-1',
      projectIdVar: options?.projectIdVar ?? 'project_id',
      environment: options?.environment ?? 'dev',
      emitComments: options?.emitComments ?? true,
      sortKeys: options?.sortKeys ?? true,
    };

    logger.info(
      { resourceCount: resources.length, region: resolved.sourceRegion },
      'Generating GCP HCL',
    );

    const files: GeneratedFiles = new Map();

    files.set('main.tf', generateMainTf(resources, resolved));
    files.set('providers.tf', generateProvidersTf(resolved));
    files.set('terraform.tf', generateTerraformTf());
    files.set('variables.tf', generateVariablesTf(resolved));
    files.set('outputs.tf', generateOutputsTf());

    logger.debug({ files: files.size }, 'GCP codegen complete');

    return files;
  }
}
